#!/usr/bin/env node
'use strict';

/**
 * Regenerates the TypeScript copy of the electronics feature-graph JSON Schemas.
 * The canonical files live in ecad-engine/contract/schemas (the backend Docker
 * build context cannot reach them, same reason reference-features.generated.ts
 * exists). Never hand-edit the generated file; a spec fails when it drifts.
 * Run from backend/:  npm run electronics:sync-contract
 */

const fs = require('fs');
const path = require('path');

const schemaDir = path.resolve(__dirname, '../../ecad-engine/contract/schemas');
const out = path.resolve(
  __dirname,
  '../src/modules/electronics-costing/domain/feature-graph/schemas.generated.ts',
);

function render() {
  const read = (name) => JSON.parse(fs.readFileSync(path.join(schemaDir, name), 'utf8'));
  return [
    '// GENERATED by scripts/sync-electronics-contract.js from ecad-engine/contract/schemas. Do not edit.',
    `export const BOARD_FEATURE_GRAPH_SCHEMA = ${JSON.stringify(read('board_feature_graph.v1.schema.json'), null, 2)} as const;`,
    '',
    `export const HARNESS_FEATURE_GRAPH_SCHEMA = ${JSON.stringify(read('harness_feature_graph.v1.schema.json'), null, 2)} as const;`,
    '',
  ].join('\n');
}

if (require.main === module) {
  fs.writeFileSync(out, render());
  console.log(`wrote ${path.relative(process.cwd(), out)}`);
}

module.exports = { render, out };
